    func test_matmul_integer() throws {
        XCTAssertClose(MfArray([200, 100] as [Int], mftype: .UInt8, shape: [1, 2]) *& MfArray([2, 1] as [Int], mftype: .UInt8, shape: [2, 1]), MfArray([244] as [Int], mftype: .UInt8, shape: [1, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([200, 100] as [Int], mftype: .UInt8, shape: [1, 2]) *& MfArray([2, 1] as [Int], mftype: .UInt8, shape: [2, 1])")
        XCTAssertClose(MfArray([100, 100] as [Int], mftype: .Int8, shape: [1, 2]) *& MfArray([1, 1] as [Int], mftype: .Int8, shape: [2, 1]), MfArray([-56] as [Int], mftype: .Int8, shape: [1, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([100, 100] as [Int], mftype: .Int8, shape: [1, 2]) *& MfArray([1, 1] as [Int], mftype: .Int8, shape: [2, 1])")
        XCTAssertClose(MfArray([200, 200, 1, 2] as [Int], mftype: .Int16, shape: [2, 2]) *& MfArray([200, 1, 200, 3] as [Int], mftype: .Int16, shape: [2, 2]), MfArray([14464, 800, 600, 7] as [Int], mftype: .Int16, shape: [2, 2]), rtol: 0, atol: 0, checkType: true, "MfArray([200, 200, 1, 2] as [Int], mftype: .Int16, shape: [2, 2]) *& MfArray([200, 1, 200, 3] as [Int], mftype: .Int16, shape: [2, 2])")
        XCTAssertClose(MfArray([300, 300] as [Int], mftype: .UInt16, shape: [1, 2]) *& MfArray([200, 200] as [Int], mftype: .UInt16, shape: [2, 1]), MfArray([54464] as [Int], mftype: .UInt16, shape: [1, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([300, 300] as [Int], mftype: .UInt16, shape: [1, 2]) *& MfArray([200, 200] as [Int], mftype: .UInt16, shape: [2, 1])")
        XCTAssertClose(MfArray([200, 100] as [Int], mftype: .UInt8, shape: [1, 2]) *& MfArray([-1, 2] as [Int], mftype: .Int8, shape: [2, 1]), MfArray([0] as [Int], mftype: .Int16, shape: [1, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([200, 100] as [Int], mftype: .UInt8, shape: [1, 2]) *& MfArray([-1, 2] as [Int], mftype: .Int8, shape: [2, 1])")
        XCTAssertClose(MfArray([3, -4] as [Int], mftype: .Int, shape: [1, 2]) *& MfArray([5, 6] as [Int], mftype: .Int, shape: [2, 1]), MfArray([-9] as [Int], mftype: .Int, shape: [1, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([3, -4] as [Int], mftype: .Int, shape: [1, 2]) *& MfArray([5, 6] as [Int], mftype: .Int, shape: [2, 1])")
        XCTAssertClose(MfArray([true, true] as [Bool], shape: [1, 2]) *& MfArray([true, true] as [Bool], shape: [2, 1]), MfArray([true] as [Bool], shape: [1, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([true, true] as [Bool], shape: [1, 2]) *& MfArray([true, true] as [Bool], shape: [2, 1])")
        XCTAssertClose(MfArray([true, false, false, false] as [Bool], shape: [2, 2]) *& MfArray([false, true, true, true] as [Bool], shape: [2, 2]), MfArray([false, true, false, false] as [Bool], shape: [2, 2]), rtol: 0, atol: 0, checkType: true, "MfArray([true, false, false, false] as [Bool], shape: [2, 2]) *& MfArray([false, true, true, true] as [Bool], shape: [2, 2])")
    }

    #if !os(WASI)
    func test_det_dtype() throws {
        XCTAssertClose(try Matft.linalg.det(MfArray([6, 1, 1, 4, -2, 5, 2, 8, 7] as [Int], mftype: .Int, shape: [3, 3])), MfArray([-306.0] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 0.0001, checkType: true, "try Matft.linalg.det(MfArray([6, 1, 1, 4, -2, 5, 2, 8, 7] as [Int], mftype: .Int, shape: [3, 3]))")
        XCTAssertClose(try Matft.linalg.det(MfArray([2, 1, 1, 1, 3, 2, 1, 0, 0] as [Int], mftype: .Int, shape: [3, 3])), MfArray([-1.0] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 0.0001, checkType: true, "try Matft.linalg.det(MfArray([2, 1, 1, 1, 3, 2, 1, 0, 0] as [Int], mftype: .Int, shape: [3, 3]))")
        XCTAssertClose(try Matft.linalg.det(MfArray([1, 2, 3, 4] as [Int], mftype: .UInt8, shape: [2, 2])), MfArray([-2.0000000000000004] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 0.0001, checkType: true, "try Matft.linalg.det(MfArray([1, 2, 3, 4] as [Int], mftype: .UInt8, shape: [2, 2]))")
        XCTAssertClose(try Matft.linalg.det(MfArray([1, 2, 3, 4] as [Int], mftype: .Int8, shape: [2, 2])), MfArray([-2.0000000000000004] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 0.0001, checkType: true, "try Matft.linalg.det(MfArray([1, 2, 3, 4] as [Int], mftype: .Int8, shape: [2, 2]))")
        XCTAssertClose(try Matft.linalg.det(MfArray([true, false, false, true] as [Bool], shape: [2, 2])), MfArray([1.0] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 0.0001, checkType: true, "try Matft.linalg.det(MfArray([true, false, false, true] as [Bool], shape: [2, 2]))")
        XCTAssertClose(try Matft.linalg.det(MfArray([1, 2, 3, 4, 2, 0, 0, 3] as [Int], mftype: .Int16, shape: [2, 2, 2])), MfArray([-2.0000000000000004, 6.0] as [Double], mftype: .Float, shape: [2]), rtol: 1e-05, atol: 0.0001, checkType: true, "try Matft.linalg.det(MfArray([1, 2, 3, 4, 2, 0, 0, 3] as [Int], mftype: .Int16, shape: [2, 2, 2]))")
        XCTAssertClose(try Matft.linalg.det(MfArray([] as [Int], mftype: .Int, shape: [0, 0])), MfArray([1.0] as [Double], mftype: .Float, shape: [1]), rtol: 1e-05, atol: 1e-05, checkType: true, "try Matft.linalg.det(MfArray([] as [Int], mftype: .Int, shape: [0, 0]))")
