    func test_square_wrap() throws {
        for (name, x) in layoutVariants(MfArray([100, -3, 12] as [Int], mftype: .Int8, shape: [3])){
            XCTAssertClose(Matft.math.square(x), MfArray([16, 9, -112] as [Int], mftype: .Int8, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.square(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([16, 15, 255] as [Int], mftype: .UInt8, shape: [3])){
            XCTAssertClose(Matft.math.square(x), MfArray([0, 225, 1] as [Int], mftype: .UInt8, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.square(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([300, 200, -181] as [Int], mftype: .Int16, shape: [3])){
            XCTAssertClose(Matft.math.square(x), MfArray([24464, -25536, 32761] as [Int], mftype: .Int16, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.square(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([300, 256, 3] as [Int], mftype: .UInt16, shape: [3])){
            XCTAssertClose(Matft.math.square(x), MfArray([24464, 0, 9] as [Int], mftype: .UInt16, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.square(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([3000, -5] as [Int], mftype: .Int, shape: [2])){
            XCTAssertClose(Matft.math.square(x), MfArray([9000000, 25] as [Int], mftype: .Int, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.square(x) \(name)")
        }
    }

    func test_power_integer() throws {
        for (name, x) in layoutVariants(MfArray([2, 3, -4] as [Int], mftype: .Int, shape: [3])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 2), MfArray([4, 9, 16] as [Int], mftype: .Int, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 2) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([16, 3, 0] as [Int], mftype: .UInt8, shape: [3])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 2), MfArray([0, 9, 0] as [Int], mftype: .UInt8, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 2) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([16, 3, 7] as [Int], mftype: .UInt8, shape: [3])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 3), MfArray([0, 27, 87] as [Int], mftype: .UInt8, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 3) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([300, -2] as [Int], mftype: .Int16, shape: [2])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 2), MfArray([24464, 4] as [Int], mftype: .Int16, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 2) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([7, 2] as [Int], mftype: .UInt8, shape: [2])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 9), MfArray([71, 0] as [Int], mftype: .UInt8, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 9) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([5, -1, 0] as [Int], mftype: .Int8, shape: [3])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 0), MfArray([1, 1, 1] as [Int], mftype: .Int8, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 0) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([2, 3] as [Int], mftype: .Int32, shape: [2])){
            XCTAssertClose(Matft.math.power(bases: x, exponents: 10), MfArray([1024, 59049] as [Int], mftype: .Int32, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: x, exponents: 10) \(name)")
        }
        XCTAssertClose(Matft.math.power(bases: MfArray([4, 9] as [Int], mftype: .Int, shape: [2]), exponents: 0.5), MfArray([2.0, 3.0] as [Double], mftype: .Float, shape: [2]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.math.power(bases: MfArray([4, 9] as [Int], mftype: .Int, shape: [2]), exponents: 0.5)")
        XCTAssertClose(Matft.math.power(bases: MfArray([1.5, -2.0] as [Double], mftype: .Float, shape: [2]), exponents: 2), MfArray([2.25, 4.0] as [Double], mftype: .Float, shape: [2]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.math.power(bases: MfArray([1.5, -2.0] as [Double], mftype: .Float, shape: [2]), exponents: 2)")
        XCTAssertClose(Matft.math.power(bases: MfArray([1.5, -2.0] as [Double], mftype: .Double, shape: [2]), exponents: 3), MfArray([3.375, -8.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.math.power(bases: MfArray([1.5, -2.0] as [Double], mftype: .Double, shape: [2]), exponents: 3)")
        XCTAssertClose(Matft.math.power(bases: MfArray([2, 6] as [Int], mftype: .UInt8, shape: [2]), exponents: MfArray([8, 3] as [Int], mftype: .UInt8, shape: [2])), MfArray([0, 216] as [Int], mftype: .UInt8, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.power(bases: MfArray([2, 6] as [Int], mftype: .UInt8, shape: [2]), exponents: MfArray([8, 3] as [Int], mftype: .UInt8, shape: [2]))")
