    func test_abs_round_integer() throws {
        for (name, x) in layoutVariants(MfArray([-128, -3, 5] as [Int], mftype: .Int8, shape: [3])){
            XCTAssertClose(Matft.math.abs(x), MfArray([-128, 3, 5] as [Int], mftype: .Int8, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.abs(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([-3, 5, 0] as [Int], mftype: .Int, shape: [3])){
            XCTAssertClose(Matft.math.abs(x), MfArray([3, 5, 0] as [Int], mftype: .Int, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.abs(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([200, 0] as [Int], mftype: .UInt8, shape: [2])){
            XCTAssertClose(Matft.math.abs(x), MfArray([200, 0] as [Int], mftype: .UInt8, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.abs(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([-32768, 7] as [Int], mftype: .Int16, shape: [2])){
            XCTAssertClose(Matft.math.abs(x), MfArray([-32768, 7] as [Int], mftype: .Int16, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.abs(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([true, false] as [Bool], shape: [2])){
            XCTAssertClose(Matft.math.abs(x), MfArray([true, false] as [Bool], shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.abs(x) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([15, 25, -3] as [Int], mftype: .Int, shape: [3])){
            XCTAssertClose(Matft.math.round(x, decimals: 0), MfArray([15, 25, -3] as [Int], mftype: .Int, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 0) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([15, 25, 1234] as [Int], mftype: .Int, shape: [3])){
            XCTAssertClose(Matft.math.round(x, decimals: -1), MfArray([20, 20, 1230] as [Int], mftype: .Int, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: -1) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([126, -125, 15, 25] as [Int], mftype: .Int8, shape: [4])){
            XCTAssertClose(Matft.math.round(x, decimals: -1), MfArray([-126, -120, 20, 20] as [Int], mftype: .Int8, shape: [4]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: -1) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([250, 5] as [Int], mftype: .UInt8, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: -1), MfArray([250, 0] as [Int], mftype: .UInt8, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: -1) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([1250, 1350] as [Int], mftype: .Int16, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: -2), MfArray([1200, 1400] as [Int], mftype: .Int16, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: -2) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([15, 7] as [Int], mftype: .Int, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: 2), MfArray([15, 7] as [Int], mftype: .Int, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 2) \(name)")
        }
    }

    func test_round_decimals() throws {
        for (name, x) in layoutVariants(MfArray([1.5, 2.25] as [Double], mftype: .Double, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: 40), MfArray([1.5, 2.25] as [Double], mftype: .Double, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 40) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([1.5, 2.25] as [Double], mftype: .Double, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: 300), MfArray([1.5, 2.25] as [Double], mftype: .Double, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 300) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([15.0, 25.0, 1234.5678, 1e+300] as [Double], mftype: .Double, shape: [4])){
            XCTAssertClose(Matft.math.round(x, decimals: -1), MfArray([20.0, 20.0, 1230.0, 1e+300] as [Double], mftype: .Double, shape: [4]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: -1) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([2.0015, 0.1234567890123] as [Double], mftype: .Double, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: 3), MfArray([2.002, 0.123] as [Double], mftype: .Double, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 3) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([123456.789, -0.5] as [Double], mftype: .Double, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: -3), MfArray([123000.0, -0.0] as [Double], mftype: .Double, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: -3) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([1.23456789012345] as [Double], mftype: .Double, shape: [1])){
            XCTAssertClose(Matft.math.round(x, decimals: 12), MfArray([1.234567890123] as [Double], mftype: .Double, shape: [1]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 12) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([2.5, 3.5, -2.5] as [Double], mftype: .Double, shape: [3])){
            XCTAssertClose(Matft.math.round(x, decimals: 0), MfArray([2.0, 4.0, -2.0] as [Double], mftype: .Double, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.math.round(x, decimals: 0) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([1.2345000505447388, 2.5] as [Double], mftype: .Float, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: 3), MfArray([1.2339999675750732, 2.5] as [Double], mftype: .Float, shape: [2]), rtol: 1e-07, atol: 0, checkType: true, "Matft.math.round(x, decimals: 3) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([15.0, 25.0, 1234.5677490234375] as [Double], mftype: .Float, shape: [3])){
            XCTAssertClose(Matft.math.round(x, decimals: -1), MfArray([20.0, 20.0, 1230.0] as [Double], mftype: .Float, shape: [3]), rtol: 1e-07, atol: 0, checkType: true, "Matft.math.round(x, decimals: -1) \(name)")
        }
        for (name, x) in layoutVariants(MfArray([0.125, -2.5] as [Double], mftype: .Float, shape: [2])){
            XCTAssertClose(Matft.math.round(x, decimals: 2), MfArray([0.11999999731779099, -2.5] as [Double], mftype: .Float, shape: [2]), rtol: 1e-07, atol: 0, checkType: true, "Matft.math.round(x, decimals: 2) \(name)")
        }
    }

