    #if !os(WASI)
    func test_div_scalar_complex() throws {
        do {
            let ret = MfArray(real: MfArray([6.0, 7.0] as [Double], mftype: .Double, shape: [2]), imag: MfArray([2002.0, -0.3] as [Double], mftype: .Double, shape: [2])) / 10.0
            XCTAssertTrue(ret.isComplex, "not complex: MfArray(real: MfArray([6.0, 7.0] as [Double], mftype: .Double, shape: [2]), imag: MfArray([2002.0, -0.3] as [Double], mftype: .Double, shape: [2])) / 10.0")
            XCTAssertClose(ret.real, MfArray([0.6000000000000001, 0.7000000000000001] as [Double], mftype: .Double, shape: [2]), rtol: 0, atol: 0, checkType: true, "real: MfArray(real: MfArray([6.0, 7.0] as [Double], mftype: .Double, shape: [2]), imag: MfArray([2002.0, -0.3] as [Double], mftype: .Double, shape: [2])) / 10.0")
            XCTAssertClose(ret.imag ?? MfArray([Double.nan]), MfArray([200.20000000000002, -0.03] as [Double], mftype: .Double, shape: [2]), rtol: 0, atol: 0, checkType: true, "imag: MfArray(real: MfArray([6.0, 7.0] as [Double], mftype: .Double, shape: [2]), imag: MfArray([2002.0, -0.3] as [Double], mftype: .Double, shape: [2])) / 10.0")
        }
    }
    #endif

    func test_equal_all_infinity() throws {
        XCTAssertTrue(MfArray([.infinity, -.infinity, 1.0] as [Double], mftype: .Double, shape: [3]) == MfArray([.infinity, -.infinity, 1.0] as [Double], mftype: .Double, shape: [3]), "MfArray([.infinity, -.infinity, 1.0] as [Double], mftype: .Double, shape: [3]) == MfArray([.infinity, -.infinity, 1.0] as [Double], mftype: .Double, shape: [3])")
        XCTAssertTrue(MfArray([.infinity, 2.0] as [Double], mftype: .Float, shape: [2]) == MfArray([.infinity, 2.0] as [Double], mftype: .Float, shape: [2]), "MfArray([.infinity, 2.0] as [Double], mftype: .Float, shape: [2]) == MfArray([.infinity, 2.0] as [Double], mftype: .Float, shape: [2])")
        XCTAssertFalse(MfArray([.infinity] as [Double], mftype: .Double, shape: [1]) == MfArray([-.infinity] as [Double], mftype: .Double, shape: [1]), "MfArray([.infinity] as [Double], mftype: .Double, shape: [1]) == MfArray([-.infinity] as [Double], mftype: .Double, shape: [1])")
        XCTAssertFalse(MfArray([.infinity, 1.0] as [Double], mftype: .Double, shape: [2]) == MfArray([.infinity, 2.0] as [Double], mftype: .Double, shape: [2]), "MfArray([.infinity, 1.0] as [Double], mftype: .Double, shape: [2]) == MfArray([.infinity, 2.0] as [Double], mftype: .Double, shape: [2])")
        XCTAssertFalse(MfArray([.nan] as [Double], mftype: .Double, shape: [1]) == MfArray([.nan] as [Double], mftype: .Double, shape: [1]), "MfArray([.nan] as [Double], mftype: .Double, shape: [1]) == MfArray([.nan] as [Double], mftype: .Double, shape: [1])")
        XCTAssertFalse(MfArray([.infinity] as [Double], mftype: .Double, shape: [1]) == MfArray([1e+300] as [Double], mftype: .Double, shape: [1]), "MfArray([.infinity] as [Double], mftype: .Double, shape: [1]) == MfArray([1e+300] as [Double], mftype: .Double, shape: [1])")
    }

    func test_where_setops_result_type() throws {
        XCTAssertClose(Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([200, 3] as [Int], mftype: .UInt8, shape: [2]), MfArray([-1] as [Int], mftype: .Int8, shape: [1])), MfArray([200, -1] as [Int], mftype: .Int16, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([200, 3] as [Int], mftype: .UInt8, shape: [2]), MfArray([-1] as [Int], mftype: .Int8, shape: [1]))")
        XCTAssertClose(Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([60000, 3] as [Int], mftype: .UInt16, shape: [2]), MfArray([-1, -1] as [Int], mftype: .Int16, shape: [2])), MfArray([60000, -1] as [Int], mftype: .Int32, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([60000, 3] as [Int], mftype: .UInt16, shape: [2]), MfArray([-1, -1] as [Int], mftype: .Int16, shape: [2]))")
        XCTAssertClose(Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([1, 2] as [Int], mftype: .Int8, shape: [2]), MfArray([200, 250] as [Int], mftype: .UInt8, shape: [2])), MfArray([1, 250] as [Int], mftype: .Int16, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([1, 2] as [Int], mftype: .Int8, shape: [2]), MfArray([200, 250] as [Int], mftype: .UInt8, shape: [2]))")
        XCTAssertClose(Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([5, 6] as [Int], mftype: .Int, shape: [2]), MfArray([7.0, 8.0] as [Double], mftype: .Float, shape: [2])), MfArray([5.0, 8.0] as [Double], mftype: .Float, shape: [2]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.where(MfArray([true, false] as [Bool], shape: [2]), MfArray([5, 6] as [Int], mftype: .Int, shape: [2]), MfArray([7.0, 8.0] as [Double], mftype: .Float, shape: [2]))")
        XCTAssertClose(Matft.union1d(MfArray([200] as [Int], mftype: .UInt8, shape: [1]), MfArray([-1] as [Int], mftype: .Int8, shape: [1])), MfArray([-1, 200] as [Int], mftype: .Int16, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.union1d(MfArray([200] as [Int], mftype: .UInt8, shape: [1]), MfArray([-1] as [Int], mftype: .Int8, shape: [1]))")
        XCTAssertClose(Matft.union1d(MfArray([60000, 1] as [Int], mftype: .UInt16, shape: [2]), MfArray([-5] as [Int], mftype: .Int16, shape: [1])), MfArray([-5, 1, 60000] as [Int], mftype: .Int32, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.union1d(MfArray([60000, 1] as [Int], mftype: .UInt16, shape: [2]), MfArray([-5] as [Int], mftype: .Int16, shape: [1]))")
        XCTAssertClose(Matft.intersect1d(MfArray([200, 1] as [Int], mftype: .UInt8, shape: [2]), MfArray([200, -1] as [Int], mftype: .Int16, shape: [2])), MfArray([200] as [Int], mftype: .Int16, shape: [1]), rtol: 0, atol: 0, checkType: true, "Matft.intersect1d(MfArray([200, 1] as [Int], mftype: .UInt8, shape: [2]), MfArray([200, -1] as [Int], mftype: .Int16, shape: [2]))")
        XCTAssertClose(Matft.intersect1d(MfArray([60000, 3] as [Int], mftype: .UInt16, shape: [2]), MfArray([-5536] as [Int], mftype: .Int16, shape: [1])), MfArray([] as [Int], mftype: .Int32, shape: [0]), rtol: 0, atol: 0, checkType: true, "Matft.intersect1d(MfArray([60000, 3] as [Int], mftype: .UInt16, shape: [2]), MfArray([-5536] as [Int], mftype: .Int16, shape: [1]))")
    }
